1	/**
2	 * Shared-hosting account provisioner (Phase 1).
3	 *
4	 * ┌────────────────────────────────────────────────────────────────────────┐
5	 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
6	 * │                                                                          │
7	 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
8	 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
9	 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
10	 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
11	 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
12	 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
13	 * │ production until this has been (1) reviewed as a security change,        │
14	 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
15	 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
16	 * │                                                                          │
17	 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
18	 * │ so a bad config can never lock the box out — but it still deserves the   │
19	 * │ staging pass.                                                            │
20	 * └────────────────────────────────────────────────────────────────────────┘
21	 *
22	 * Everything a shell touches is validated through the tested pure helpers in
23	 * lib/hosting.ts BEFORE interpolation.
24	 */
25	
26	import { Client } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { promises as dns } from "node:dns";
29	import { db } from "../lib/db";
30	import { SANDBOX } from "../lib/sandbox";
31	import { decryptSecret, encryptSecret } from "../lib/crypto-box";
32	import {
33	  isValidUnixUsername,
34	  isValidHostingDomain,
35	  isValidSubdomainLabel,
36	  isValidCronSchedule,
37	  isValidCronCommand,
38	  subdomainPaths,
39	  addonDomainPaths,
40	  planLimits,
41	  diskQuotaBlocks,
42	  accountPaths,
43	  accountFsPlan,
44	  fpmPoolConfig,
45	  buildScopedGrantSql,
46	} from "../lib/hosting";
47	
48	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
49	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
50	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
51	 *  doesn't treat them as command substitution. */
52	function sqlForMysqlExec(sql: string): string {
53	  return sql.replace(/`/g, "\\`");
54	}
55	
56	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
57	const CONNECT_TIMEOUT_MS = 20_000;
58	const STEP_TIMEOUT_MS = 60_000;
59	
60	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
61	function strongPassword(len = 22): string {
62	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
63	  const bytes = randomBytes(len);
64	  let out = "";
65	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
66	  return out;
67	}
68	
69	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
70	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
71	  if (!password) throw new Error("Hosting node has no root credential on record.");
72	  const conn = new Client();
73	  await new Promise<void>((resolve, reject) => {
74	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
75	    conn
76	      .on("ready", () => { clearTimeout(timer); resolve(); })
77	      .on("error", (e) => { clearTimeout(timer); reject(e); })
78	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
79	  });
80	  return conn;
81	}
82	
83	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
84	  return new Promise((resolve, reject) => {
85	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
86	    conn.exec(command, (err, stream) => {
87	      if (err) { clearTimeout(timer); return reject(err); }
88	      let out = "";
89	      stream
90	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
91	        .on("data", (d: Buffer) => { out += d.toString(); })
92	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
93	    });
94	  });
95	}
96	
97	async function run(conn: Client, label: string, cmd: string): Promise<void> {
98	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
99	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
100	}
101	
102	/**
103	 * The name-based nginx vhost for one account — HTTP-only until a cert exists, and
104	 * HTTP→HTTPS + a 443 SNI block once it does. Shared IP; routed purely by
105	 * server_name; PHP proxied to THIS account's socket only, root jailed to its
106	 * webroot. Pure string — no interpolation reaches a shell here.
107	 */
108	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, sslLiveDir: string | null): string {
109	  const phpLoc = [
110	    `    location ~ \\.php$ {`,
111	    `        include fastcgi_params;`,
112	    `        fastcgi_pass unix:${sock};`,
113	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
114	    `    }`,
115	  ].join("\n");
116	  const body = [
117	    `    root ${webroot};`,
118	    `    index index.php index.html;`,
119	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
120	    phpLoc,
121	    `    location ~ /\\. { deny all; }`,
122	  ].join("\n");
123	  const http = [
124	    `server {`,
125	    `    listen 80;`,
126	    `    listen [::]:80;`,
127	    `    server_name ${domain} www.${domain};`,
128	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
129	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
130	    `}`,
131	  ].join("\n");
132	  if (!sslLiveDir) return http + "\n";
133	  const https = [
134	    `server {`,
135	    `    listen 443 ssl;`,
136	    `    listen [::]:443 ssl;`,
137	    `    server_name ${domain} www.${domain};`,
138	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
139	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
140	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
141	    body,
142	    `}`,
143	  ].join("\n");
144	  return `${http}\n${https}\n`;
145	}
146	
147	/** Write a vhost file + enable it, tested before reload. */
148	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
149	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
150	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
151	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
152	}
153	
154	/**
155	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
156	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
157	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
158	 * interpolation reaches a shell here (the caller validated every part).
159	 */
160	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
161	  const phpLoc = [
162	    `    location ~ \\.php$ {`,
163	    `        include fastcgi_params;`,
164	    `        fastcgi_pass unix:${sock};`,
165	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
166	    `    }`,
167	  ].join("\n");
168	  const body = [
169	    `    root ${docroot};`,
170	    `    index index.php index.html;`,
171	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
172	    phpLoc,
173	    `    location ~ /\\. { deny all; }`,
174	  ].join("\n");
175	  const http = [
176	    `server {`,
177	    `    listen 80;`,
178	    `    listen [::]:80;`,
179	    `    server_name ${serverName};`,
180	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
181	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
182	    `}`,
183	  ].join("\n");
184	  if (!sslLiveDir) return http + "\n";
185	  const https = [
186	    `server {`,
187	    `    listen 443 ssl;`,
188	    `    listen [::]:443 ssl;`,
189	    `    server_name ${serverName};`,
190	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
191	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
192	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
193	    body,
194	    `}`,
195	  ].join("\n");
196	  return `${http}\n${https}\n`;
197	}
198	
199	/** Write + enable a vhost under an arbitrary key (hosting-<key>.conf), tested
200	 *  before reload. Used for subdomain / addon-domain sites (key = <user>-<label>
201	 *  or <user>-<domain>); the account's own primary vhost keeps its <user> filename. */
202	async function installNamedVhost(conn: Client, key: string, conf: string): Promise<void> {
203	  const path = `/etc/nginx/sites-available/hosting-${key}.conf`;
204	  await run(conn, "write site vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${key}.conf`);
205	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
206	}
207	
208	/** Remove a named site vhost (enabled + available), tested before reload. */
209	async function removeNamedVhost(conn: Client, key: string): Promise<void> {
210	  await run(conn, "remove site vhost", `rm -f /etc/nginx/sites-enabled/hosting-${key}.conf /etc/nginx/sites-available/hosting-${key}.conf; nginx -t && systemctl reload nginx || true`);
211	}
212	
213	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
214	 *  contents (the PHP isolation boundary) come from the tested pure generator in
215	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
216	 *  needs editing when PHP is switched. */
217	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
218	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
219	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
220	}
221	
222	/**
223	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
224	 * sweep once DNS points at us). Every interpolated value has already cleared a
225	 * validator, so nothing here can be a shell metacharacter.
226	 */
227	async function applyIsolation(
228	  conn: Client,
229	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
230	  php: string,
231	): Promise<void> {
232	  const u = a.username;
233	  const d = a.primaryDomain;
234	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
235	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
236	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
237	  const { home, webroot } = accountPaths(u);
238	  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
239	  const softBlocks = Math.floor(hardBlocks * 0.95);
240	  const sock = `/run/php/${u}.sock`;
241	
242	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
243	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
244	  //
245	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
246	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
247	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
248	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
249	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
250	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
251	  const fs = accountFsPlan(u);
252	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
253	  await run(
254	    conn,
255	    "chroot-safe home",
256	    `mkdir -p ${webroot} ${home}/tmp && ` +
257	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
258	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
259	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
260	  );
261	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
262	
263	  // 2. Disk quota (fs must have usrquota — node onboarding enables it).
264	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
265	
266	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
267	  await writeFpmPool(conn, u, home, webroot, php);
268	
269	  // 4. Name-based vhost (HTTP only for now).
270	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, null));
271	
272	  // 5. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
273	  const sftpConf = [
274	    `Match User ${u}`,
275	    `    ChrootDirectory ${home}`,
276	    `    ForceCommand internal-sftp`,
277	    `    AllowTcpForwarding no`,
278	    `    X11Forwarding no`,
279	  ].join("\n");
280	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
281	  await run(
282	    conn,
283	    "sftp chroot (guarded)",
284	    // Write to a temp include, validate the WHOLE sshd config, and only then move
285	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
286	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
287	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
288	  );
289	}
