291	// ---- DB provisioning (per-account, on demand) ------------------------------
292	
293	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
294	async function provisionHostingDatabase(dbId: string): Promise<void> {
295	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
296	  if (!rec || rec.status !== "PENDING") return;
297	  if (SANDBOX || !ENABLED) {
298	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
299	    return;
300	  }
301	  const name = rec.name;
302	  const user = rec.dbUser;
303	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
304	  // DB name + user were built from the validated username; re-assert shape.
305	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
306	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
307	    return;
308	  }
309	  try {
310	    const conn = await connectNode(rec.account.node);
311	    try {
312	      // Grants scoped to THIS database only — the data-isolation boundary.
313	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
314	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
315	      await run(conn, "create database", `mysql -e "${sql}"`);
316	    } finally {
317	      try { conn.end(); } catch { /* */ }
318	    }
319	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
320	  } catch (e) {
321	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
322	  }
323	}
324	
325	export async function hostingDatabaseSweep(): Promise<void> {
326	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
327	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
328	}
329	
330	// ---- Account provisioning --------------------------------------------------
331	
332	export async function provisionHostingAccount(accountId: string): Promise<void> {
333	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
334	  if (!account || account.status !== "PENDING") return;
335	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
336	
337	  if (SANDBOX || !ENABLED) {
338	    if (SANDBOX) {
339	      const pw = strongPassword();
340	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
341	    } else {
342	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
343	    }
344	    return;
345	  }
346	
347	  try {
348	    const allowed = planLimits(account.plan).phpVersions;
349	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
350	    const sftpPassword = strongPassword();
351	    const conn = await connectNode(account.node);
352	    try {
353	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
354	    } finally {
355	      try { conn.end(); } catch { /* */ }
356	    }
357	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
358	  } catch (e) {
359	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
360	  }
361	}
362	
363	export async function hostingProvisionSweep(): Promise<void> {
364	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
365	  for (const p of pending) await provisionHostingAccount(p.id).catch((e) => console.error(`[hosting] provision ${p.id} failed`, e));
366	}
367	
368	// ---- SSL sweep (post-DNS, no sshd risk) ------------------------------------
369	
370	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
371	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
372	  try {
373	    const a = await dns.resolve4(domain);
374	    return a.includes(ip);
375	  } catch {
376	    return false;
377	  }
378	}
379	
380	/**
381	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
382	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
383	 * block. Safe: touches only nginx + certbot, never sshd.
384	 */
385	export async function hostingSslSweep(): Promise<void> {
386	  if (SANDBOX || !ENABLED) return;
387	  const accts = await db.hostingAccount.findMany({
388	    where: { status: "ACTIVE", sslActive: false },
389	    include: { node: true },
390	    take: 20,
391	  });
392	  for (const a of accts) {
393	    try {
394	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
395	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
396	      const d = a.primaryDomain;
397	      const conn = await connectNode(a.node);
398	      try {
399	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
400	        const liveDir = `/etc/letsencrypt/live/${d}`;
401	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
402	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
403	        const { webroot } = accountPaths(a.username);
404	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, liveDir));
405	      } finally {
406	        try { conn.end(); } catch { /* */ }
407	      }
408	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
409	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
410	    } catch (e) {
411	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
412	    }
413	  }
414	
415	  // Addon domains get their own per-domain cert the same way, once they resolve
416	  // to the node's shared IP. (Subdomains are left for a wildcard-cert follow-up.)
417	  const addons = await db.hostingAddonDomain.findMany({
418	    where: { status: "ACTIVE", sslActive: false },
419	    include: { account: { include: { node: true } } },
420	    take: 20,
421	  });
422	  for (const ad of addons) {
423	    try {
424	      const u = ad.account.username;
425	      const d = ad.domain;
426	      if (!isValidHostingDomain(d) || !isValidUnixUsername(u)) continue;
427	      if (!(await domainPointsAt(d, ad.account.node.publicIp))) continue; // DNS not pointed yet
428	      const conn = await connectNode(ad.account.node);
429	      try {
430	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
431	        const liveDir = `/etc/letsencrypt/live/${d}`;
432	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
433	        if (have.out.trim() !== "yes") { console.log(`[hosting] addon cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
434	        const { docroot } = addonDomainPaths(u, d);
