436	      } finally {
437	        try { conn.end(); } catch { /* */ }
438	      }
439	      await db.hostingAddonDomain.update({ where: { id: ad.id }, data: { sslActive: true } });
440	      console.log(`[hosting] HTTPS active for addon ${d}`);
441	    } catch (e) {
442	      console.error(`[hosting] addon ssl sweep ${ad.id} failed`, e);
443	    }
444	  }
