447	/** Measure real disk + inode usage per ACTIVE account and store it, so the panel
448	 *  shows live meters instead of a placeholder. Read-only on the node (du + find);
449	 *  inert until enabled. Polled on the SSL-sweep cadence. */
450	export async function hostingUsageSweep(): Promise<void> {
451	  if (SANDBOX || !ENABLED) return;
452	  const accts = await db.hostingAccount.findMany({ where: { status: "ACTIVE" }, include: { node: true }, take: 50 });
453	  for (const a of accts) {
454	    try {
455	      if (!isValidUnixUsername(a.username)) continue;
456	      const conn = await connectNode(a.node);
457	      try {
458	        const du = await exec(conn, `du -sm /home/${a.username} 2>/dev/null | cut -f1`, 60_000);
459	        const inodes = await exec(conn, `find /home/${a.username} -xdev 2>/dev/null | wc -l`, 60_000);
460	        const diskUsedMB = parseInt(du.out.trim(), 10);
461	        const inodesUsed = parseInt(inodes.out.trim(), 10);
462	        await db.hostingAccount.update({
463	          where: { id: a.id },
464	          data: {
465	            diskUsedMB: Number.isFinite(diskUsedMB) ? diskUsedMB : null,
466	            inodesUsed: Number.isFinite(inodesUsed) ? inodesUsed : null,
467	            usageAt: new Date(),
468	          },
469	        });
470	      } finally {
471	        try { conn.end(); } catch { /* */ }
472	      }
473	    } catch (e) {
474	      console.error(`[hosting] usage sweep ${a.id} failed`, e);
475	    }
476	  }
477	}
