501	// ---- Account lifecycle (suspend / unsuspend / terminate) --------------------
502	// All three validate the username first (it flows into shell), and are written to
503	// be idempotent + safe to re-run. They only touch this account's own files.
504	
505	type LifecycleAccount = { id: string; username: string; phpVersion: string };
506	
507	// Validate BOTH shell-bound fields up front. username is a strict allowlist;
508	// phpVersion is stored (schema default "8.3") but re-checked here so it can never
509	// carry anything but `\d.\d` into an `rm`/`systemctl` line (security audit LOW-1).
510	function assertLifecycleSafe(a: LifecycleAccount): void {
511	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
512	  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
513	}
