515	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
516	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
517	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
518	  assertLifecycleSafe(a);
519	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
520	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
521	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
522	}
523	
524	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
525	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
526	  assertLifecycleSafe(a);
527	  const { home, webroot } = accountPaths(a.username);
528	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
529	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
530	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
531	}
