603	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
604	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
605	  const slug = String(p.slug ?? "");
606	  const recipe = APP_RECIPES[slug];
607	  if (!recipe) throw new Error("unknown app");
608	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
609	  const u = a.username;
610	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
611	  const { webroot } = accountPaths(u);
612	  const isBz2 = recipe.url.endsWith(".bz2");
613	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
614	  // Download + extract into the webroot AS the account user (jailed).
615	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
616	  let dbInfo = "";
617	  if (recipe.needsDb) {
618	    const dbName = String(p.dbName ?? "");
619	    const dbUser = String(p.dbUser ?? "");
620	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
621	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
622	    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
623	    await run(conn, "app db", `mysql -e "${sql}"`);
624	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
625	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
626	  }
627	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
628	}
