630	/** Archive the account's home + DB dumps to a node-local backups dir.
631	 *
632	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
633	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
634	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
635	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
636	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
637	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
638	 * dumps root-owned and off the tenant tree means the archived SQL is always our
639	 * own mysqldump output, never tenant-controlled. */
640	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
641	  const u = a.username;
642	  const dir = `/var/hosting-backups/${u}`;
643	  const dumpDir = `${dir}/dbdump`;
644	  const path = `${dir}/${tsLabel}.tar.gz`;
645	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
646	  // tenant can neither read nor tamper with it.
647	  await run(
648	    conn,
649	    "dump dbs",
650	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
651	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
652	  );
653	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
654	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
655	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
656	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
657	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
658	  // Retain the newest 5 per account; delete older files + rows.
659	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
660	  for (const old of all.slice(5)) {
661	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
662	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
663	  }
664	}
