666	/** Restore a backup over the account (destructive: overwrites files + DBs).
667	 *
668	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
669	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
670	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
671	 * database, and the SQL content is our own dump, not anything the tenant could
672	 * have planted (see taskBackup). */
673	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
674	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
675	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
676	  if (!b) throw new Error("backup not found");
677	  const u = a.username;
678	  const { home, webroot } = accountPaths(u);
679	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
680	  const stage = `/var/hosting-backups/${u}/.restore`;
681	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
682	  // Files: the archive root holds ${u}/… — copy it back over the home.
683	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
684	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
685	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
686	  // another tenant's DB is never fed to mysql.
687	  await run(
688	    conn,
689	    "restore dbs",
690	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
691	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
692	  );
693	  // Re-assert the hardened perms the restored tree may have flattened: webroot
694	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
695	  const rfs = accountFsPlan(u);
696	  await run(
697	    conn,
698	    "fix perms",
699	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
700	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
701	  );
702	}
