757	async function taskCreateAddonDomain(conn: Client, a: SiteAccount, payload: string | null): Promise<void> {
758	  const addonId = String(JSON.parse(payload || "{}").addonId ?? "");
759	  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
