788	/** (Re)write the account user's crontab from its ACTIVE cron rows. Runs `crontab
789	 *  -u <user>` so every command runs AS the jailed user (confined). The whole
790	 *  crontab is rebuilt each time (idempotent); a quoted heredoc prevents any shell
791	 *  expansion, and each line is re-validated so nothing unsafe is ever written. */
792	async function writeUserCrontab(conn: Client, username: string, accountId: string): Promise<void> {
793	  if (!isValidUnixUsername(username)) throw new Error("unsafe account username");
794	  const crons = await db.hostingCron.findMany({ where: { accountId, status: "ACTIVE" }, orderBy: { createdAt: "asc" } });
795	  const lines = crons
796	    .filter((c) => isValidCronSchedule(c.schedule) && isValidCronCommand(c.command))
797	    .map((c) => `${c.schedule} ${c.command}`);
798	  if (lines.length === 0) {
799	    await run(conn, "clear crontab", `crontab -u ${username} -r 2>/dev/null || true`);
800	    return;
801	  }
802	  const body = lines.join("\n") + "\n";
803	  await run(conn, "write crontab", `crontab -u ${username} - <<'NXCRONEOF'\n${body}NXCRONEOF`);
