826	async function processHostingTask(taskId: string): Promise<void> {
827	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
828	  if (!task || task.status !== "PENDING") return;
829	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
830	  const a = task.account;
831	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
832	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
833	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
834	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
835	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
836	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
837	  try {
838	    const conn = await connectNode(a.node);
839	    try {
840	      let result: string | null = null;
841	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
842	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
843	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
844	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
845	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
846	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
847	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
848	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
849	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
850	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
851	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
852	      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
853	      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
854	      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
855	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
856	    } finally { try { conn.end(); } catch { /* */ } }
857	  } catch (e) {
858	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
859	  }
