227	/** Create a scoped database for an account (within the plan's maxDatabases). */
228	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
229	  const user = await requireUser();
230	  await assertNotImpersonating();
231	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
232	  if (!a) return { error: "Account not found." };
233	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
234	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
235	  // A short, safe suffix keyed off the account username: <user>_<slug>.
236	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
237	  const name = `${a.username}_${slug}`.slice(0, 64);
238	  const dbUser = name.slice(0, 32);
239	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
240	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
241	  // Count + create in ONE serializable transaction, so concurrent creates can't
242	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
243	  try {
244	    await db.$transaction(async (tx) => {
245	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
246	      if (n >= a.maxDatabases) throw new Error("CAP");
247	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
248	    }, { isolationLevel: "Serializable" });
249	  } catch (e) {
250	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
251	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
252	    return { error: "A database with that name already exists, or the request raced — try again." };
253	  }
254	  revalidatePath("/dashboard/hosting");
255	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
256	  return { ok: true, password };
257	}
