442	/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
443	async function ownedSiteAccount(id: string) {
444	  const user = await requireUser();
445	  // Impersonating admins must not create/destroy customer resources — cron is
446	  // arbitrary command execution as the customer's unix user; subdomains/addons
447	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
448	  await assertNotImpersonating();
449	  const a = await db.hostingAccount.findUnique({
450	    where: { id },
451	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
452	  });
453	  if (!a) return { error: "Account not found." as const };
454	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
455	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
456	  return { user, a };
