459	/**
460	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
461	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
462	 * subdomain, or an addon domain. Before this, each creator only checked its own
463	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
464	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
465	 * This single check, used by all three creators, is the app-level invariant (no DB
466	 * unique can span three tables + a deliberately re-usable primaryDomain).
467	 */
468	async function isHostnameClaimed(name: string): Promise<boolean> {
469	  const [prim, sub, addon] = await Promise.all([
470	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
471	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
472	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
473	  ]);
474	  return prim + sub + addon > 0;
475	}
