513	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
514	  const ctx = await ownedSiteAccount(accountId);
515	  if ("error" in ctx) return { error: ctx.error };
516	  const { a } = ctx;
517	  const clean = String(label ?? "").trim().toLowerCase();
518	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
519	  const fqdn = `${clean}.${a.primaryDomain}`;
520	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
521	  // Reject if another tenant already claimed this exact hostname as an addon domain
522	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
523	  // path (audit HIGH-1, reverse direction).
524	  if (await isHostnameClaimed(fqdn)) {
525	    return { error: "That hostname is already in use on Nxeon." };
526	  }
527	  const { docroot } = subdomainPaths(a.username, clean);
528	  try {
529	    await db.$transaction(async (tx) => {
530	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
531	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
532	      if (subs + addons >= a.maxSites) throw new Error("CAP");
533	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
534	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
535	    }, { isolationLevel: "Serializable" });
536	  } catch (e) {
537	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
538	    return { error: "That subdomain already exists, or the request raced — try again." };
539	  }
540	  revalidatePath(`/dashboard/hosting/${accountId}`);
541	  return { ok: true };
542	}
