555	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
556	  const ctx = await ownedSiteAccount(accountId);
557	  if ("error" in ctx) return { error: ctx.error };
558	  const { a } = ctx;
559	  const name = normalizeHostingDomain(domain);
560	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
561	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
562	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
563	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
564	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
565	  if (await isHostnameClaimed(name)) {
