567	  }
568	  const { docroot } = addonDomainPaths(a.username, name);
569	  try {
570	    await db.$transaction(async (tx) => {
571	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
572	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
573	      if (subs + addons >= a.maxSites) throw new Error("CAP");
574	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
575	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
576	    }, { isolationLevel: "Serializable" });
577	  } catch (e) {
578	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
579	    return { error: "That domain is already added, or the request raced — try again." };
580	  }
581	  revalidatePath(`/dashboard/hosting/${accountId}`);
582	  return { ok: true };
