// 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
await writeFpmPool(conn, u, home, webroot, php);

// 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
//    second the account exists. Without this the account served HTTP-only until
//    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
//    while the panel already said "active" (the kaymo failure). Idempotent: only
//    generated if absent. Key is 600 root; the whole dir is root-owned + off the
//    tenant tree, so a tenant can never read or swap its own TLS key.
const ssCertDir = selfSignedCertDir(u);
await run(
  conn,
  "self-signed fallback cert",
  `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
    `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
    `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
    `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
    `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
);

// 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
//    until the SSL sweep swaps in the real Let's Encrypt cert.
await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));

