// ---- Serve-verification + self-heal health sweep ---------------------------

/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
 *  when curl couldn't get a response (connection refused/timeout → "000"). */
function parseHttpCode(out: string): number {
  const n = parseInt(out.trim().slice(-3), 10);
  return Number.isFinite(n) ? n : 0;
}
/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
 *  (we never mark an account falsely healthy). */
function servesOk(code: number): boolean {
  return code >= 200 && code < 400;
}

/**
 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
 * curls http/https for each account's own Host header and records whether nginx
 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
 * ~10-min tick. Returns the number of accounts processed.
 */
export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
  const onlyRequested = opts.onlyRequested === true;
  if (SANDBOX) {
    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
    const accts = await db.hostingAccount.findMany({
      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
      select: { id: true, sslActive: true },
      take: onlyRequested ? 25 : 50,
    });
    for (const a of accts) {
      await db.hostingAccount.update({
        where: { id: a.id },
        data: {
          serveHttpOk: true,
          serveHttpsOk: true,
          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
          healthCheckedAt: new Date(),
          recheckRequested: false,
        },
      }).catch(() => undefined);
    }
    return accts.length;
  }
  if (!ENABLED) return 0;

  const accts = await db.hostingAccount.findMany({
    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
    include: { node: true },
    // Newest-requested first so a customer who just clicked "Check now" is served
    // before the routine backlog even in the full sweep.
    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
    take: onlyRequested ? 25 : 30,
  });
  let processed = 0;
  for (const a of accts) {
    try {
      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
      const d = a.primaryDomain;
      const u = a.username;
      let serveHttpOk = false;
      let serveHttpsOk = false;
      let sslActive = a.sslActive;
      let note = "";
      const conn = await connectNode(a.node);
      try {
        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
        serveHttpOk = servesOk(parseHttpCode(httpR.out));
        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));

        // Does a REAL Let's Encrypt cert exist on the node for this domain?
        const liveDir = `/etc/letsencrypt/live/${d}`;
        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";

        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
        // re-verify. This is the recovery from exactly the state kaymo hit.
        if (haveReal && !serveHttpsOk) {
          const { webroot } = accountPaths(u);
          try {
            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
            serveHttpsOk = servesOk(parseHttpCode(reR.out));
            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
          } catch (e) {
            note = "HTTPS repair failed — support notified";
            console.error(`[hosting] health self-heal ${a.id} failed`, e);
          }
        }
        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live

        if (!note) {
          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
          else {
            // Nothing served locally. If DNS isn't pointed at us yet, say so;
            // otherwise it's a serving fault the SSL sweep / support will chase.
            const pointed = await domainPointsAt(d, a.node.publicIp);
            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
          }
        }
      } finally {
        try { conn.end(); } catch { /* */ }
      }
      await db.hostingAccount.update({
        where: { id: a.id },
        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
      });
      processed++;
    } catch (e) {
      console.error(`[hosting] health sweep ${a.id} failed`, e);
      // Clear the recheck flag even on failure so a broken node can't wedge the
      // fast path into re-processing the same account every 30s forever.
      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
    }
  }
  return processed;
}

