 * trusted certificate can start issuing. Owner or admin; a no-op for non-active
 * accounts (nothing to verify until it's provisioned).
 */
export async function recheckHostingHealth(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { userId: true, status: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  await db.hostingAccount.update({ where: { id }, data: { recheckRequested: true } });
  revalidatePath(`/dashboard/hosting/${id}`);
  return { ok: true };
}

